UNDRESSED_WEIGHTS = (sp.Integer(0),) * 4
PLUS_SITES = list(range(HALF))           # the carrier half p = 0,1
MINUS_SITES = list(range(HALF, PHYS))    # p = 2,3
CELLS = tuple((t, x) for t in range(PHYS_T) for x in range(LX))
ODD_CELLS = tuple((t, x) for t in (1, 3) for x in range(LX))
EDGE_KEYS = tuple(
    (INDEX[left], INDEX[right]) for left in ORIGINS for right in ORIGINS
)

# the four independent moduli of one cell: nu, a = nu/(1-sg^2),
# b = -nu*sg/(1-sg^2) and 1/nu.  They are REAL, so .H is .T on every matrix
# built from them.
NU_MODULUS = {c: sp.Symbol(f"n_{c[0]}{c[1]}", real=True) for c in CELLS}
A_MODULUS = {c: sp.Symbol(f"a_{c[0]}{c[1]}", real=True) for c in CELLS}
B_MODULUS = {c: sp.Symbol(f"b_{c[0]}{c[1]}", real=True) for c in CELLS}
INV_MODULUS = {c: sp.Symbol(f"m_{c[0]}{c[1]}", real=True) for c in CELLS}
COORDS = tuple(
    table[c]
    for c in CELLS
    for table in (NU_MODULUS, A_MODULUS, B_MODULUS, INV_MODULUS)
)
SHEAR_COORDS = tuple(B_MODULUS[c] for c in CELLS)
ODD_SHEAR_COORDS = tuple(B_MODULUS[c] for c in ODD_CELLS)
NON_SHEAR_COORDS = tuple(c for c in COORDS if c not in set(SHEAR_COORDS))


def cover_index(t: int, x: int) -> int:
    return (t % COVER_T) * LX + (x % LX)


def cover_hodge_general(nu_value, a_value, b_value, inverse_value) -> sp.Matrix:
    """The cover Hodge assembled from per-cell moduli.

    This is b142.hodge_from_field with the per-cell local Hodge left in its
    linear coordinates (nu, a, b, 1/nu) instead of the nonlinear (sigma, nu);
    gate B pins the two against each other on a symbolic sub-family and on the
    committed fixtures.
    """
    hodge = sp.zeros(SIZE, SIZE)
    for t in range(COVER_T):
        for x in range(LX):
            cell = (t % PHYS_T, x)
            nu = nu_value[cell]
            a = a_value[cell]
            b = b_value[cell]
            inverse = inverse_value[cell]
            hodge[cover_index(t, x), cover_index(t, x)] += nu / 4
            hodge[cover_index(t, x + 1), cover_index(t, x + 1)] += a / 4
            hodge[cover_index(t + 1, x), cover_index(t + 1, x)] += a / 4
            hodge[
                cover_index(t + 1, x + 1), cover_index(t + 1, x + 1)
            ] += inverse / 4
            hodge[cover_index(t, x + 1), cover_index(t + 1, x)] += b / 4
            hodge[cover_index(t + 1, x), cover_index(t, x + 1)] += b / 4
    return hodge


def quotient(hodge: sp.Matrix) -> sp.Matrix:
    """The antiperiodic quotient; identical to b134.antiperiodic_quotient."""
    return sp.Matrix(
        PHYS,
        PHYS,
        lambda i, j: sp.expand(hodge[PHYS + i, PHYS + j] - hodge[PHYS + i, j]),
    )


def moduli_from_field(field: dict) -> tuple[dict, dict, dict, dict]:
    """(nu, a, b, 1/nu) per cell from a (sigma, nu) carrier field."""
    nu_value, a_value, b_value, inverse_value = {}, {}, {}, {}
    for cell, (shear, volume) in field.items():
        nu_value[cell] = volume
        a_value[cell] = volume / (1 - shear ** 2)
        b_value[cell] = -volume * shear / (1 - shear ** 2)
        inverse_value[cell] = 1 / volume
    return nu_value, a_value, b_value, inverse_value


def cover_hodge_from_field(field: dict) -> sp.Matrix:
    return cover_hodge_general(*moduli_from_field(field))


def quotient_action(differential: sp.Matrix, hodge: sp.Matrix, mass) -> sp.Matrix:
    """Q = quotient(m H + i(H d + d^dagger H)); b137.quotient_action's law.

    Written out here because the committed routine spends its time on generic
    simplification, which is ten times slower on the 64-modulus family; gate B
    pins this against b137.quotient_action symbolically and on the fixture.
    """
    return quotient(
        sp.expand(
            mass * hodge
            + sp.I * (hodge * differential + differential.H * hodge)
        )
    )


def pairing(action: sp.Matrix) -> sp.Matrix:
    """P = [theta Q]_{++} on the half carrier {p = 0,1} (H1)."""
    return sp.expand(PLUS.T * THETA * action * PLUS)


def connection(shear_x, shear_t) -> tuple[dict, sp.Matrix]:
    data = b137.connection_data(shear_x, shear_t)
    return data["d"], sp.expand(data["d"][(0, 0)] - data["d"][(1, 0)])


def edge_differentials(differentials, star, weights) -> dict:
    """The 16 healed edge differentials d_i + lambda_ij Omega*."""
    return {
        (INDEX[left], INDEX[right]): sp.expand(
            differentials[left]
            + (weights[INDEX[right]] - weights[INDEX[left]]) * star
        )
        for left in ORIGINS
        for right in ORIGINS
    }


def hermiticity_rows(block: sp.Matrix) -> list[list]:
    """Coefficient rows of "P is Hermitian identically in m" (H2).

    Everything here is real, so the condition is P[i,j] = P[j,i]; each such
    condition is a polynomial in m whose every coefficient is an exact linear
    form in the 64 moduli, and each nonzero coefficient contributes one row.
    """
    rows: list[list] = []
    for i in range(block.rows):
        for j in range(i + 1, block.cols):
            defect = sp.expand(block[i, j] - block[j, i])
            for coefficient in sp.Poly(defect, MASS).all_coeffs():
                coefficient = sp.expand(coefficient)
                if coefficient != 0:
                    rows.append(
                        [coefficient.coeff(value, 1) for value in COORDS]
                    )
    return rows


def linear_form(row) -> sp.Expr:
    return sp.expand(
        sum(row[k] * COORDS[k] for k in range(len(COORDS)))
    )


def is_linear_in_moduli(matrix: sp.MatrixBase) -> bool:
    """Every entry is homogeneous of degree <= 1 in the 64 moduli."""
    origin = {value: 0 for value in COORDS}
    if not zero(matrix.subs(origin)):
        return False
    for entry in matrix:
        entry = sp.expand(entry)
        if entry == 0:
            continue
        if sp.Poly(entry, *COORDS).total_degree() > 1:
            return False
    return True


def row_basis(rows) -> sp.Matrix:
    """A reduced basis of the row space; empty rows give a 0-row matrix."""
    if not rows:
        return sp.zeros(0, len(COORDS))
    reduced, pivots = sp.Matrix(rows).rref()
    if not pivots:
        return sp.zeros(0, len(COORDS))
    return sp.Matrix([list(reduced[k, :]) for k in range(len(pivots))])


def hermitian_edge_set(hodge: sp.Matrix, differentials: dict) -> tuple:
    """The edges whose half pairing is Hermitian on one concrete carrier."""
    found = []
    for key in sorted(differentials):
        block = pairing(quotient_action(differentials[key], hodge, MASS))
        if zero_simplified(block - block.T):
            found.append(key)
    return tuple(found)


def flat_field(**overrides) -> dict:
    """nu = 1, sigma = 0 everywhere, with named cells overridden."""
    field = {c: (sp.Integer(0), sp.Integer(1)) for c in CELLS}
    for name, volume in overrides.items():
        field[(int(name[2]), int(name[3]))] = (sp.Integer(0), volume)
    return field


# ---------------------------------------------------------------------------
# the certificate constants this runner is claiming
# ---------------------------------------------------------------------------
# the eight nonzero seam entries, each a single odd-time-slice shear moment
SEAM_TABLE = (
    (0, 5, B_MODULUS[(1, 0)] / 4),
    (1, 6, B_MODULUS[(1, 1)] / 4),
    (2, 7, B_MODULUS[(1, 2)] / 4),
    (3, 4, B_MODULUS[(1, 3)] / 4),
    (4, 3, -B_MODULUS[(3, 3)] / 4),
    (5, 0, -B_MODULUS[(3, 0)] / 4),
    (6, 1, -B_MODULUS[(3, 1)] / 4),
    (7, 2, -B_MODULUS[(3, 2)] / 4),
)
SEAM_INJECTIVE_RANK = 8
SYSTEM_RANK = 18
KERNEL_DIM = 46
MODULUS_DIM = 64
HODGE_INERTIA = (PHYS, 0, 0)

# the two x-alternating volume forms generating the residual system
RESIDUAL_RANK = 2
RESIDUAL_FORMS = (
    A_MODULUS[(0, 1)] - A_MODULUS[(0, 3)]
    + A_MODULUS[(1, 0)] - A_MODULUS[(1, 2)]
    + INV_MODULUS[(0, 0)] - INV_MODULUS[(0, 2)]
    + NU_MODULUS[(1, 1)] - NU_MODULUS[(1, 3)],
    A_MODULUS[(2, 1)] - A_MODULUS[(2, 3)]
    + A_MODULUS[(3, 0)] - A_MODULUS[(3, 2)]
    + INV_MODULUS[(2, 0)] - INV_MODULUS[(2, 2)]
    + NU_MODULUS[(3, 1)] - NU_MODULUS[(3, 3)],
)

# the calibration triple: what the model must reproduce on committed carriers
CALIBRATION_STAIRCASE = ()
CALIBRATION_CONSTANT = ((1, 2),)
CALIBRATION_CONSTANT_FIELD = (R(3, 5), R(4, 5))
CALIBRATION_SHEAR_FREE = 16

# the converse counterexample and its restoration
COUNTEREXAMPLE_SURVIVORS = ((0, 0), (0, 1), (1, 0), (1, 1))
RESTORED_HERMITIAN_EDGES = 16

# the live-seam residue, as corrected by the independent checker
LIVE_BOUND = 2
LIVE_SINGLETON_COUNT = 12
LIVE_PAIRS = (
    ((2, 0), (2, 1)),
    ((2, 2), (3, 3)),
    ((2, 3), (3, 2)),
    ((3, 0), (3, 1)),
)
EVEN_LEFT_SINGLETONS = (((0, 2),), ((0, 3),), ((1, 2),), ((1, 3),))
MAXIMAL_LIVE_SETS = tuple(sorted(EVEN_LEFT_SINGLETONS + LIVE_PAIRS))
MAXIMAL_LIVE_COUNT = 8

# the self-edge witness
WITNESS_STRONG_CELLS = ((1, 1), (1, 3), (3, 1), (3, 3))
WITNESS_WEAK_CELLS = ((1, 0), (1, 2), (3, 0), (3, 2))
WITNESS_STRONG = (R(3, 5), sp.Integer(1))
WITNESS_WEAK = (R(15, 32), R(799, 512))
WITNESS_EDGES = ((2, 2), (3, 3))
WITNESS_SEAM_RANK = 8
WITNESS_INERTIAS = frozenset({(6, 0, 2), (2, 0, 6)})

# the even-left carrier that corrects the odd-left-only reading
EVEN_LEFT_CARRIER_EVEN_SLICE = (R(-3, 5), sp.Integer(3))
EVEN_LEFT_CARRIER_ODD_SLICE = (R(3, 5), sp.Integer(1))
EVEN_LEFT_EDGE = (0, 2)
EVEN_LEFT_SEAM_RANK = 8

# the split mass Gram on the mass-block Hermiticity locus
MASS_GRAM_LOCUS = (
    (B_MODULUS[(1, 0)], B_MODULUS[(1, 3)]),
    (B_MODULUS[(1, 1)], B_MODULUS[(1, 2)]),
    (B_MODULUS[(3, 0)], B_MODULUS[(3, 3)]),
    (B_MODULUS[(3, 1)], B_MODULUS[(3, 2)]),
)
MASS_GRAM_BLOCKS = ((0, 3), (1, 2), (4, 5), (6, 7))
MASS_GRAM_GENERATORS = (
    B_MODULUS[(3, 3)],
    B_MODULUS[(3, 2)],
    B_MODULUS[(1, 3)],
    B_MODULUS[(1, 2)],
)

# the X_0 complement
X0_GRAM_INERTIA = (4, 0, 4)
X0_HERMITIAN_EDGES = 16
THETA_HERMITIAN_EDGES_ON_FAMILY = 0
DET_BETA = EPS ** 8 / (65536 * (1 - EPS ** 2) ** 8)
EPS_PROBE = R(3, 5)
EPS_JORDAN_TYPE = (2, 2, 1, 1, 1, 1)
EPS_JORDAN_INDEX = 2
EPS_NILPOTENT_EDGES = 4
STAIRCASE_JORDAN_TYPE = b143.NILPOTENT_JORDAN_TYPE      # (3, 3, 1, 1)
STAIRCASE_JORDAN_INDEX = b143.NILPOTENT_INDEX           # 3

ODD_SELECTOR = sp.Matrix(
    [
        [1 if COORDS[k] == moment else 0 for k in range(len(COORDS))]
        for moment in ODD_SHEAR_COORDS
    ]
)


def witness_field() -> dict:
    field = {c: (sp.Integer(0), sp.Integer(1)) for c in CELLS}
    for cell in WITNESS_STRONG_CELLS:
        field[cell] = WITNESS_STRONG
    for cell in WITNESS_WEAK_CELLS:
        field[cell] = WITNESS_WEAK
    return field


def even_left_field() -> dict:
    return {
        cell: (
            EVEN_LEFT_CARRIER_EVEN_SLICE
            if cell[0] % 2 == 0
            else EVEN_LEFT_CARRIER_ODD_SLICE
        )
        for cell in CELLS
    }


def in_admissible_cone(field: dict) -> bool:
    """nu > 0 and |sigma| < 1 on every cell (H4)."""
    return all(
        volume > 0 and sp.Abs(shear) < 1 for shear, volume in field.values()
    )


def seam_can_live(bases) -> bool:
    """Does some carrier obeying these edges' Hermiticity have a LIVE seam?

    The Hermiticity conditions of a set of edges cut out a linear subspace; the
    seam Gram is the eight odd-slice moments, so the seam is dead on that
    subspace exactly when every odd-moment coordinate functional lies in the
    row space of the conditions.  That is a pair of ranks, not a nullspace
    enumeration, which is what keeps the exhaustive subset search cheap.
    """
    live_rows = [basis for basis in bases if basis.rows]
    if not live_rows:
        return True
    stacked = sp.Matrix.vstack(*live_rows)
    return sp.Matrix.vstack(stacked, ODD_SELECTOR).rank() > stacked.rank()


# ---------------------------------------------------------------------------
# measured facts (computed once, before any mutation flag is consulted)
# ---------------------------------------------------------------------------
@dataclass(frozen=True)
class Facts:
    main_head: str
    authority: AuthorityCertificate
    # B: linearity, the builder calibration and the seam law
    inertia_calibration: bool
    hodge_linear_in_moduli: bool
    quotient_linear_in_moduli: bool
    builder_matches_symbolic_subfamily: bool
    builder_matches_committed_fixtures: bool
    quotient_matches_b134: bool
    carrier_matches_b144: bool
    action_matches_b137: bool
    pairing_matches_b142: bool
    seam_table: tuple
    seam_support_is_odd_shear: bool
    seam_injective_rank: int
    seam_zero_when_odd_shear_free: bool
    moment_vanishes_iff_shear_vanishes: bool
    shear_free_quotient_diagonal: bool
    diagonal_law_x_dependent: bool
    diagonal_law_reduces_to_block144: bool
    block144_slice_values: tuple
    # C: the necessity theorem
    system_rank: int
    kernel_dim: int
    kernel_forces_shear_free: bool
    alt_certificate: tuple
    undressed_certificate: tuple
    symbolic_kernel_annihilates: bool
    symbolic_rows: int
    calibration_staircase: tuple
    calibration_constant: tuple
    calibration_shear_free: int
    # D: the converse refinement
    residual_rank: int
    residual_forms_span_row_space: bool
    counterexample_hermitian_edges: tuple
    counterexample_survivors_are_null: bool
    counterexample_violates_first_form: bool
    restoration_hermitian_edges: int
    restoration_hodge_inertia: tuple
    restoration_seam_zero: bool
    # E: the live-seam residue
    live_singletons: tuple
    live_pairs: tuple
    live_triples: tuple
    maximal_live_sets: tuple
    witness_in_cone: bool
    witness_hermitian_edges: tuple
    witness_seam_rank: int
    witness_hodge_inertia: tuple
    witness_mass_present: bool
    witness_inertias: frozenset
    even_left_in_cone: bool
    even_left_hermitian_edges: tuple
    even_left_seam_rank: int
    even_left_hodge_inertia: tuple
    # F: the split mass Gram
    mass_gram_zero_diagonal: bool
    mass_gram_locus_is_claimed: bool
    mass_gram_locus_zero_diagonal: bool
    mass_gram_block_support: tuple
    mass_gram_charpoly_splits: bool
    mass_gram_psd_on_live_sublocus: bool
    mass_gram_vanishes_at_dead_point: bool
    # G: the X_0 complement
    x0_commutes_with_quotient: bool
    x0_anticommutes_with_currents: int
    x0_hermitian_healed: int
    x0_hermitian_alt: int
    x0_hermitian_undressed: int
    theta_hermitian_on_family: int
    x0_gram_inertias: tuple
    det_beta: sp.Expr
    eps_nilpotent_edges: int
    eps_jordan_types: frozenset
    eps_jordan_indices: frozenset
    staircase_jordan_type: tuple
    staircase_jordan_index: int
    # global
    exact_no_float: bool
    scope: dict


def measure() -> Facts:
    main_head = git_output("rev-parse", "origin/main")
    authority = authority_certificate(main_head)

    # The congruence routine is calibrated here, in the measurement pass, on
    # matrices whose inertia is known by inspection and on which the
    # root-counting helper of Blocks 142/143 is provably wrong.
    inertia_calibration = bool(
        congruence_inertia(sp.diag(1, 2, -3, R(5, 7))) == (3, 0, 1)
        and congruence_inertia(sp.diag(1, 1, -2, -2, 0)) == (2, 1, 2)
        and b142.inertia(sp.diag(1, 1, -2, -2, 0)) != (2, 1, 2)
    )

    # --- the one symbolic carrier.  Nothing else builds a free Hodge. ------
    hodge = cover_hodge_general(
        NU_MODULUS, A_MODULUS, B_MODULUS, INV_MODULUS
    )
    hodge_quotient = quotient(hodge)

    # --- B: the builder calibration ---------------------------------------
    slice_shear = sp.symbols("sg0 sg1 sg2 sg3", real=True)
    slice_volume = sp.symbols("vl0 vl1 vl2 vl3", positive=True)
    subfamily = {
        cell: (slice_shear[cell[0]], slice_volume[cell[0]]) for cell in CELLS
    }
    builder_matches_symbolic_subfamily = zero_simplified(
        cover_hodge_from_field(subfamily) - b142.hodge_from_field(subfamily)
    )
    staircase_field = b105.overlap_field()
    staircase_hodge = cover_hodge_from_field(staircase_field)
    builder_matches_committed_fixtures = bool(
        zero(staircase_hodge - b142.hodge_from_field(staircase_field))
        and zero(staircase_hodge - b134.curved_hodge_cover())
    )
    quotient_matches_b134 = zero(
        quotient(staircase_hodge) - b134.antiperiodic_quotient(staircase_hodge)
    )
    block144_fixture_field = {
        (t, x): (sp.Integer(0), b144.NU_FIXTURE[t])
        for t in range(PHYS_T)
        for x in range(LX)
    }
    carrier_matches_b144 = zero(
        quotient(cover_hodge_from_field(block144_fixture_field))
        - b144.carrier(b144.NU_FIXTURE)
    )

    fixture_differentials, fixture_star = connection(b134.S_X, b134.S_T)
    fixture_edges = edge_differentials(
        fixture_differentials, fixture_star, HEALING_WEIGHTS
    )
    probe_edge = fixture_edges[(2, 3)]
    probe_action = quotient_action(probe_edge, hodge, MASS)
    action_matches_b137 = zero(
        probe_action - sp.expand(b137.quotient_action(probe_edge, hodge, MASS))
    )
    pairing_matches_b142 = zero(
        pairing(probe_action) - b142.pairing(THETA, probe_action)
    )

    # --- B: the seam law ---------------------------------------------------
    seam = hodge_quotient[MINUS_SITES, PLUS_SITES]
    seam_table = tuple(
        (i, j, sp.expand(seam[i, j]))
        for i in range(HALF)
        for j in range(HALF)
        if sp.expand(seam[i, j]) != 0
    )
    seam_symbols: set = set()
    for _, _, entry in seam_table:
        seam_symbols |= entry.free_symbols
    seam_support_is_odd_shear = seam_symbols == set(ODD_SHEAR_COORDS)
    seam_injective_rank = sp.Matrix(
        [
            [sp.expand(seam[i, j]).coeff(moment, 1) for moment in ODD_SHEAR_COORDS]
            for i in range(HALF)
            for j in range(HALF)
        ]
    ).rank()

    # the physical reading: the seam moments ARE the odd-slice shears
    physical_shear = {c: sp.Symbol(f"sg_{c[0]}{c[1]}", real=True) for c in CELLS}
    physical_volume = {
        c: sp.Symbol(f"vl_{c[0]}{c[1]}", positive=True) for c in CELLS
    }
    physical = {}
    for cell in CELLS:
        shear = physical_shear[cell]
        volume = physical_volume[cell]
        physical[NU_MODULUS[cell]] = volume
        physical[A_MODULUS[cell]] = volume / (1 - shear ** 2)
        physical[B_MODULUS[cell]] = -volume * shear / (1 - shear ** 2)
        physical[INV_MODULUS[cell]] = 1 / volume
    odd_shear_off = {physical_shear[cell]: 0 for cell in ODD_CELLS}
    seam_zero_when_odd_shear_free = zero_simplified(
        seam.subs(physical).subs(odd_shear_off)
    )
    sample_cell = ODD_CELLS[0]
    moment_vanishes_iff_shear_vanishes = sp.solve(
        sp.Eq(physical[B_MODULUS[sample_cell]], 0), physical_shear[sample_cell]
    ) == [0]

    # --- B: the diagonal law on the zero-shear stratum ---------------------
    free_volume = {
        c: sp.Symbol(f"vf_{c[0]}{c[1]}", positive=True) for c in CELLS
    }
    shear_free_quotient = quotient(
        cover_hodge_from_field(
            {cell: (sp.Integer(0), free_volume[cell]) for cell in CELLS}
        )
    )
    shear_free_quotient_diagonal = zero_simplified(
        shear_free_quotient
        - sp.diag(*[shear_free_quotient[k, k] for k in range(PHYS)])
    )
    diagonal_law_x_dependent = all(
        sp.simplify(
            shear_free_quotient[p * LX + y, p * LX + y]
            - (
                free_volume[(p, y)]
                + free_volume[(p, (y - 1) % LX)]
                + free_volume[((p - 1) % PHYS_T, y)]
                + 1 / free_volume[((p - 1) % PHYS_T, (y - 1) % LX)]
            )
            / 4
        )
        == 0
        for p in range(PHYS_T)
        for y in range(LX)
    )
    slice_only = sp.symbols("t0 t1 t2 t3", positive=True)
    to_slice = {
        free_volume[(p, y)]: slice_only[p]
        for p in range(PHYS_T)
        for y in range(LX)
    }
    diagonal_law_reduces_to_block144 = all(
        sp.simplify(
            shear_free_quotient[p * LX + y, p * LX + y].subs(to_slice)
            - (
                2 * slice_only[p]
                + slice_only[(p - 1) % PHYS_T]
                + 1 / slice_only[(p - 1) % PHYS_T]
            )
            / 4
        )
        == 0
        for p in range(PHYS_T)
        for y in range(LX)
    )
    block144_slice_values = tuple(
        sp.simplify(
            shear_free_quotient[p * LX, p * LX]
            .subs(to_slice)
            .subs(
                {
                    slice_only[k]: b144.NU_FIXTURE[k]
                    for k in range(PHYS_T)
                }
            )
        )
        for p in range(PHYS_T)
    )

    # --- C: the necessity theorem -----------------------------------------
    fixture_blocks = {
        key: pairing(quotient_action(fixture_edges[key], hodge, MASS))
        for key in EDGE_KEYS
    }
    fixture_rows = {key: hermiticity_rows(fixture_blocks[key]) for key in EDGE_KEYS}
    system = sp.Matrix(
        [row for key in sorted(fixture_rows) for row in fixture_rows[key]]
    )
    system_rank = system.rank()
    kernel = system.nullspace()
    shear_indices = [COORDS.index(moment) for moment in SHEAR_COORDS]
    kernel_forces_shear_free = all(
        sp.simplify(vector[index]) == 0
        for vector in kernel
        for index in shear_indices
    )

    def weight_certificate(weights) -> tuple:
        edges = edge_differentials(
            fixture_differentials, fixture_star, weights
        )
        rows = [
            row
            for key in sorted(edges)
            for row in hermiticity_rows(
                pairing(quotient_action(edges[key], hodge, MASS))
            )
        ]
        matrix = sp.Matrix(rows)
        null = matrix.nullspace()
        return (
            matrix.rank(),
            len(null),
            all(
                sp.simplify(vector[index]) == 0
                for vector in null
                for index in shear_indices
            ),
        )

    alt_certificate = weight_certificate(ALT_WEIGHTS)
    undressed_certificate = weight_certificate(UNDRESSED_WEIGHTS)

    # symbolic connection fixture: rank cannot drop under specialisation, so
    # the symbolic rank is at least the fixture's 18; the fixture's 46-dim
    # kernel annihilating the symbolic system caps it at 18 as well.
    symbolic_x, symbolic_t = sp.symbols("s_x s_t", real=True, nonzero=True)
    symbolic_differentials, symbolic_star = connection(symbolic_x, symbolic_t)
    symbolic_edges = edge_differentials(
        symbolic_differentials, symbolic_star, HEALING_WEIGHTS
    )
    symbolic_actions = {
        key: quotient_action(symbolic_edges[key], hodge, MASS)
        for key in EDGE_KEYS
    }
    symbolic_system = sp.Matrix(
        [
            row
            for key in sorted(symbolic_actions)
            for row in hermiticity_rows(pairing(symbolic_actions[key]))
        ]
    )
    symbolic_kernel_annihilates = all(
        zero_simplified(symbolic_system * vector) for vector in kernel
    )

    # --- C: the calibration triple ----------------------------------------
    calibration_staircase = hermitian_edge_set(staircase_hodge, fixture_edges)
    calibration_constant = hermitian_edge_set(
        cover_hodge_from_field(
            {cell: CALIBRATION_CONSTANT_FIELD for cell in CELLS}
        ),
        fixture_edges,
    )
    calibration_shear_free = len(
        hermitian_edge_set(
            cover_hodge_from_field(
                {
                    (t, x): (sp.Integer(0), b105.OVERLAP_SHEARS[t][1])
                    for t in range(PHYS_T)
                    for x in range(LX)
                }
            ),
            fixture_edges,
        )
    )

    # --- D: the converse refinement ---------------------------------------
    shear_off = {moment: 0 for moment in SHEAR_COORDS}
    residual_rows = []
    for key in sorted(fixture_rows):
        for row in fixture_rows[key]:
            form = sp.expand(linear_form(row).subs(shear_off))
            if form != 0:
                residual_rows.append(
                    [form.coeff(value, 1) for value in NON_SHEAR_COORDS]
                )
    residual = sp.Matrix(residual_rows)
    residual_rank = residual.rank()
    expected_forms = sp.Matrix(
        [
            [sp.expand(form).coeff(value, 1) for value in NON_SHEAR_COORDS]
            for form in RESIDUAL_FORMS
        ]
    )
    residual_forms_span_row_space = bool(
        expected_forms.rank() == len(RESIDUAL_FORMS)
        and sp.Matrix.vstack(residual, expected_forms).rank() == residual_rank
    )

    counterexample_field = flat_field(nu01=sp.Integer(2))
    counterexample_hodge = cover_hodge_from_field(counterexample_field)
    counterexample_hermitian_edges = hermitian_edge_set(
        counterexample_hodge, fixture_edges
    )
    counterexample_survivors_are_null = all(
        zero(
            pairing(
                quotient_action(fixture_edges[key], counterexample_hodge, MASS)
            )
        )
        for key in counterexample_hermitian_edges
    )
    counterexample_volume = {
        NU_MODULUS[c]: counterexample_field[c][1] for c in CELLS
    }
    counterexample_volume.update(
        {A_MODULUS[c]: counterexample_field[c][1] for c in CELLS}
    )
    counterexample_volume.update(
        {INV_MODULUS[c]: 1 / counterexample_field[c][1] for c in CELLS}
    )
    counterexample_violates_first_form = bool(
        sp.simplify(RESIDUAL_FORMS[0].subs(counterexample_volume)) != 0
        and sp.simplify(RESIDUAL_FORMS[1].subs(counterexample_volume)) == 0
    )

    restoration_field = flat_field(nu01=sp.Integer(2), nu03=sp.Integer(2))
    restoration_hodge = cover_hodge_from_field(restoration_field)
    restoration_quotient = quotient(restoration_hodge)
    restoration_hermitian_edges = len(
        hermitian_edge_set(restoration_hodge, fixture_edges)
    )
    restoration_hodge_inertia = congruence_inertia(restoration_quotient)
    restoration_seam_zero = zero(
        restoration_quotient[MINUS_SITES, PLUS_SITES]
    )

    # --- E: the live-seam residue -----------------------------------------
    bases = {key: row_basis(fixture_rows[key]) for key in EDGE_KEYS}
    ordered = sorted(EDGE_KEYS)
    live_singletons = tuple(
        key for key in ordered if seam_can_live([bases[key]])
    )
    live_pairs = tuple(
        subset
        for subset in combinations(ordered, 2)
        if seam_can_live([bases[key] for key in subset])
    )
    live_triples = tuple(
        subset
        for subset in combinations(ordered, 3)
        if seam_can_live([bases[key] for key in subset])
    )
    covered = {key for subset in live_pairs for key in subset}
    maximal_live_sets = tuple(
        sorted(
            list(live_pairs)
            + [(key,) for key in live_singletons if key not in covered]
        )
    )

    witness = witness_field()
    witness_hodge = cover_hodge_from_field(witness)
    witness_quotient = quotient(witness_hodge)
    witness_hermitian_edges = hermitian_edge_set(witness_hodge, fixture_edges)
    witness_blocks = {
        key: pairing(quotient_action(fixture_edges[key], witness_hodge, MASS))
        for key in witness_hermitian_edges
    }
    witness_mass_present = all(
        MASS in block.free_symbols for block in witness_blocks.values()
    )
    witness_inertias = frozenset(
        congruence_inertia(sp.expand(block.subs(MASS, b134.MASS)))
        for block in witness_blocks.values()
    )

    even_left = even_left_field()
    even_left_hodge = cover_hodge_from_field(even_left)
    even_left_quotient = quotient(even_left_hodge)
    even_left_hermitian_edges = hermitian_edge_set(
        even_left_hodge, fixture_edges
    )

    # --- F: the split mass Gram -------------------------------------------
    mass_gram = sp.expand(PLUS.T * THETA * hodge_quotient * PLUS)
    mass_gram_zero_diagonal = all(
        sp.expand(mass_gram[i, i]) == 0 for i in range(HALF)
    )
    mass_conditions = [
        sp.expand(mass_gram[i, j] - mass_gram[j, i])
        for i in range(HALF)
        for j in range(i + 1, HALF)
    ]
    mass_conditions = [row for row in mass_conditions if row != 0]
    claimed_locus = sp.Matrix(
        [
            [
                sp.expand(left - right).coeff(moment, 1)
                for moment in ODD_SHEAR_COORDS
            ]
            for left, right in MASS_GRAM_LOCUS
        ]
    )
    measured_locus = sp.Matrix(
        [
            [sp.expand(row).coeff(moment, 1) for moment in ODD_SHEAR_COORDS]
            for row in mass_conditions
        ]
    )
    mass_gram_locus_is_claimed = bool(
        claimed_locus.rank() == len(MASS_GRAM_LOCUS)
        and measured_locus.rank() == len(MASS_GRAM_LOCUS)
        and sp.Matrix.vstack(measured_locus, claimed_locus).rank()
        == len(MASS_GRAM_LOCUS)
    )
    locus_substitution = {left: right for left, right in MASS_GRAM_LOCUS}
    locus_gram = sp.expand(mass_gram.subs(locus_substitution))
    mass_gram_locus_zero_diagonal = all(
        sp.expand(locus_gram[i, i]) == 0 for i in range(HALF)
    )
    # the support is read as unordered index pairs: the Gram is symmetric, so
    # each hyperbolic block shows up twice in the entrywise scan.
    mass_gram_block_support = tuple(
        sorted(
            {
                (min(i, j), max(i, j))
                for i in range(HALF)
                for j in range(HALF)
                if sp.expand(locus_gram[i, j]) != 0
            }
        )
    )
    mass_gram_charpoly_splits = sp.simplify(
        sp.expand(locus_gram.charpoly(SPECTRAL).as_expr())
        - sp.prod(
            [
                SPECTRAL ** 2 - generator ** 2 / 16
                for generator in MASS_GRAM_GENERATORS
            ]
        )
    ) == 0
    live_samples = []
    for generator in MASS_GRAM_GENERATORS:
        sample = {
            moment: (1 if moment == generator else 0)
            for moment in MASS_GRAM_GENERATORS
        }
        live_samples.append(sp.expand(locus_gram.subs(sample)))
    mass_gram_psd_on_live_sublocus = any(
        congruence_inertia(sample)[2] == 0 for sample in live_samples
    )
    mass_gram_vanishes_at_dead_point = zero(
        locus_gram.subs({moment: 0 for moment in MASS_GRAM_GENERATORS})
    )

    # --- G: the X_0 complement ---------------------------------------------
    x0_commutes_with_quotient = zero(
        X0 * hodge_quotient - hodge_quotient * X0
    )
    x0_anticommutes_with_currents = sum(
        1
        for key in EDGE_KEYS
        if zero(
            X0 * sp.expand(symbolic_actions[key] - MASS * hodge_quotient)
            + sp.expand(symbolic_actions[key] - MASS * hodge_quotient) * X0
        )
    )

    def x0_hermitian_count(weights) -> int:
        edges = edge_differentials(
            symbolic_differentials, symbolic_star, weights
        )
        count = 0
        for key in sorted(edges):
            action = quotient_action(edges[key], hodge, MASS)
            paired = sp.expand(X0.H * action)
            if zero(paired - paired.H):
                count += 1
        return count

    x0_hermitian_healed = sum(
        1
        for key in EDGE_KEYS
        if zero(
            sp.expand(X0.H * symbolic_actions[key])
            - sp.expand(X0.H * symbolic_actions[key]).H
        )
    )
    x0_hermitian_alt = x0_hermitian_count(ALT_WEIGHTS)
    x0_hermitian_undressed = x0_hermitian_count(UNDRESSED_WEIGHTS)
    theta_hermitian_on_family = sum(
        1
        for key in EDGE_KEYS
        if zero(
            sp.expand(THETA.H * symbolic_actions[key])
            - sp.expand(THETA.H * symbolic_actions[key]).H
        )
    )
    x0_gram_inertias = tuple(
        congruence_inertia(
            sp.expand(PLUS.T * X0 * quotient(cover_hodge_from_field(field)) * PLUS)
        )
        for field in (
            staircase_field,
            witness,
            {cell: (sp.Integer(0), sp.Integer(1)) for cell in CELLS},
        )
    )

    eps_quotient = quotient(
        cover_hodge_from_field({cell: (EPS, sp.Integer(1)) for cell in CELLS})
    )
    det_beta = sp.factor(
        sp.simplify(eps_quotient[MINUS_SITES, PLUS_SITES].det())
    )
    eps_hodge = cover_hodge_from_field(
        {cell: (EPS_PROBE, sp.Integer(1)) for cell in CELLS}
    )
    eps_carrier_quotient = quotient(eps_hodge)
    beta_inverse = eps_carrier_quotient[MINUS_SITES, PLUS_SITES].inv()
    eps_types = []
    for key in EDGE_KEYS:
        current = sp.expand(
            quotient_action(fixture_edges[key], eps_hodge, MASS)
            - MASS * eps_carrier_quotient
        )
        report = b143.spectral_report(
            sp.expand(beta_inverse * current[MINUS_SITES, PLUS_SITES])
        )
        eps_types.append((report["kind"], report["index"], report["jordan"]))
    eps_nilpotent = [entry for entry in eps_types if entry[0] == "nilpotent"]

    exact_no_float = no_float(
        (
            hodge_quotient,
            seam,
            tuple(entry for _, _, entry in seam_table),
            shear_free_quotient,
            system,
            residual,
            witness_quotient,
            even_left_quotient,
            restoration_quotient,
            locus_gram,
            eps_carrier_quotient,
            det_beta,
            block144_slice_values,
            tuple(witness_blocks.values()),
        )
    )

    return Facts(
        main_head=main_head,
        authority=authority,
        inertia_calibration=inertia_calibration,
        hodge_linear_in_moduli=is_linear_in_moduli(hodge),
        quotient_linear_in_moduli=is_linear_in_moduli(hodge_quotient),
        builder_matches_symbolic_subfamily=builder_matches_symbolic_subfamily,
        builder_matches_committed_fixtures=builder_matches_committed_fixtures,
        quotient_matches_b134=quotient_matches_b134,
        carrier_matches_b144=carrier_matches_b144,
        action_matches_b137=action_matches_b137,
        pairing_matches_b142=pairing_matches_b142,
        seam_table=seam_table,
        seam_support_is_odd_shear=seam_support_is_odd_shear,
        seam_injective_rank=seam_injective_rank,
        seam_zero_when_odd_shear_free=seam_zero_when_odd_shear_free,
        moment_vanishes_iff_shear_vanishes=moment_vanishes_iff_shear_vanishes,
        shear_free_quotient_diagonal=shear_free_quotient_diagonal,
        diagonal_law_x_dependent=diagonal_law_x_dependent,
        diagonal_law_reduces_to_block144=diagonal_law_reduces_to_block144,
        block144_slice_values=block144_slice_values,
        system_rank=system_rank,
        kernel_dim=len(kernel),
        kernel_forces_shear_free=kernel_forces_shear_free,
        alt_certificate=alt_certificate,
        undressed_certificate=undressed_certificate,
        symbolic_kernel_annihilates=symbolic_kernel_annihilates,
        symbolic_rows=symbolic_system.rows,
        calibration_staircase=calibration_staircase,
        calibration_constant=calibration_constant,
        calibration_shear_free=calibration_shear_free,
        residual_rank=residual_rank,
        residual_forms_span_row_space=residual_forms_span_row_space,
        counterexample_hermitian_edges=counterexample_hermitian_edges,
        counterexample_survivors_are_null=counterexample_survivors_are_null,
        counterexample_violates_first_form=counterexample_violates_first_form,
        restoration_hermitian_edges=restoration_hermitian_edges,
        restoration_hodge_inertia=restoration_hodge_inertia,
        restoration_seam_zero=restoration_seam_zero,
        live_singletons=live_singletons,
        live_pairs=live_pairs,
        live_triples=live_triples,
        maximal_live_sets=maximal_live_sets,
        witness_in_cone=in_admissible_cone(witness),
        witness_hermitian_edges=witness_hermitian_edges,
        witness_seam_rank=witness_quotient[MINUS_SITES, PLUS_SITES].rank(),
        witness_hodge_inertia=congruence_inertia(witness_quotient),
        witness_mass_present=witness_mass_present,
        witness_inertias=witness_inertias,
        even_left_in_cone=in_admissible_cone(even_left),
        even_left_hermitian_edges=even_left_hermitian_edges,
        even_left_seam_rank=even_left_quotient[MINUS_SITES, PLUS_SITES].rank(),
        even_left_hodge_inertia=congruence_inertia(even_left_quotient),
        mass_gram_zero_diagonal=mass_gram_zero_diagonal,
        mass_gram_locus_is_claimed=mass_gram_locus_is_claimed,
        mass_gram_locus_zero_diagonal=mass_gram_locus_zero_diagonal,
        mass_gram_block_support=mass_gram_block_support,
        mass_gram_charpoly_splits=mass_gram_charpoly_splits,
        mass_gram_psd_on_live_sublocus=mass_gram_psd_on_live_sublocus,
        mass_gram_vanishes_at_dead_point=mass_gram_vanishes_at_dead_point,
        x0_commutes_with_quotient=x0_commutes_with_quotient,
        x0_anticommutes_with_currents=x0_anticommutes_with_currents,
        x0_hermitian_healed=x0_hermitian_healed,
        x0_hermitian_alt=x0_hermitian_alt,
        x0_hermitian_undressed=x0_hermitian_undressed,
        theta_hermitian_on_family=theta_hermitian_on_family,
        x0_gram_inertias=x0_gram_inertias,
        det_beta=det_beta,
        eps_nilpotent_edges=len(eps_nilpotent),
        eps_jordan_types=frozenset(entry[2] for entry in eps_nilpotent),
        eps_jordan_indices=frozenset(entry[1] for entry in eps_nilpotent),
        staircase_jordan_type=STAIRCASE_JORDAN_TYPE,
        staircase_jordan_index=STAIRCASE_JORDAN_INDEX,
        exact_no_float=exact_no_float,
        scope=scope_certificate(raw_note()),
    )


