def scope_certificate(note_text: str) -> dict[str, bool]:
    note = normalized_note(note_text)
    compact = compact_note(note_text)
    return {
        "seam_law_eight": "eight" in note
        and ("odd-time-slice" in note or "odd-slice" in note),
        "seam_injectivity": "injectiv" in note,
        "necessity_rank": "rank 18" in note,
        "necessity_kernel": "forces shear-free" in note or "kernel" in note,
        "converse_residual": "two residual" in note
        and ("volume" in note or "x-alternating" in note),
        "converse_not_sufficient": "not sufficient" in note,
        "dichotomy": "the mass never enters" in note,
        "live_singletons_even": "singletons" in note
        and "cover-time-even" in note,
        "live_pairs_odd": "pairs" in note and "cover-time-odd" in note,
        "live_bound": "at most two" in note,
        "witness": "799/512" in note,
        "split_gram": "hyperbolic" in note or "exactly split" in note,
        "vacuous_caveat": "vacuously" in note,
        "x0_carrier_uniform": "carrier-uniform" in note,
        # Whitespace-insensitive so the note may write (4, 0, 4) or (4,0,4).
        "x0_gram": "(4,0,4)" in compact,
        "x0_discontinuity": "does not deform continuously" in note,
        "tooling_disclosure": "congruence" in note,
        "independence_disclosure": "cross-context" in note,
        "os_no_go": "not an os no-go" in note,
        "curved_os_no_go": "not a curved os no-go" in note,
        "axiom": "no axiom amendment is justified" in note,
        "firewalls": "firewall" in note,
        "zero_retirement": "zero obligation retirement" in note,
        "zero_score": (
            "no toe percentage moves" in note
            or "no toe percentage movement" in note
        ),
        "zero_e2e": (
            "retained-positive end-to-end theory count remains zero" in note
        ),
        "n1_n8": all(
            re.search(rf"\bn{index}\b", note) is not None
            for index in range(1, 9)
        ),
        "w1": re.search(r"\bw1\b", note) is not None,
        # Raw substring membership makes the printed eight-line fence
        # byte-identical to its note occurrence.
        "n5_verbatim": N5_FENCE in note_text,
    }


# ---------------------------------------------------------------------------
# claims: the only thing a mutation is allowed to touch
# ---------------------------------------------------------------------------
def build_claims(mutation: str) -> dict[str, object]:
    claims: dict[str, object] = {
        "main_head": CURRENT_MAIN,
        "parent_pin": "resolved",
        "seam_table": SEAM_TABLE,
        "seam_injective_rank": SEAM_INJECTIVE_RANK,
        "system_rank": SYSTEM_RANK,
        "necessity_is_weight_uniform": True,
        "residual_rank": RESIDUAL_RANK,
        "counterexample_hermitian_edges": COUNTEREXAMPLE_SURVIVORS,
        "maximal_live_sets": MAXIMAL_LIVE_SETS,
        "maximal_live_count": MAXIMAL_LIVE_COUNT,
        "witness_hermitian_edges": WITNESS_EDGES,
        "mass_gram_psd_on_live_sublocus": False,
        "x0_commutes": True,
        "det_beta": DET_BETA,
        "required_scope_keys": SCOPE_KEYS,
    }
    if mutation == "stale_main_authority":
        claims["main_head"] = STALE_MAIN
    elif mutation == "stale_parent_authority":
        claims["parent_pin"] = "stale"
    elif mutation == "wrong_seam_entry":
        claims["seam_table"] = tuple(
            (i, j, -entry if (i, j) == (3, 4) else entry)
            for i, j, entry in SEAM_TABLE
        )
    elif mutation == "break_seam_injectivity":
        claims["seam_injective_rank"] = SEAM_INJECTIVE_RANK - 1
    elif mutation == "wrong_system_rank":
        claims["system_rank"] = SYSTEM_RANK - 1
    elif mutation == "claim_dressing_dependence":
        claims["necessity_is_weight_uniform"] = False
    elif mutation == "wrong_residual_rank":
        claims["residual_rank"] = RESIDUAL_RANK + 1
    elif mutation == "break_counterexample":
        claims["counterexample_hermitian_edges"] = COUNTEREXAMPLE_SURVIVORS + (
            (2, 2),
        )
    elif mutation == "claim_odd_left_only":
        claims["maximal_live_sets"] = tuple(sorted(LIVE_PAIRS))
    elif mutation == "wrong_live_set_count":
        claims["maximal_live_count"] = MAXIMAL_LIVE_COUNT - 1
    elif mutation == "break_witness":
        claims["witness_hermitian_edges"] = ((2, 2), (2, 3))
    elif mutation == "claim_positive_semidefinite_mass_gram":
        claims["mass_gram_psd_on_live_sublocus"] = True
    elif mutation == "break_x0_commutator":
        claims["x0_commutes"] = False
    elif mutation == "wrong_det_beta":
        claims["det_beta"] = EPS ** 8 / (65536 * (1 - EPS ** 2) ** 7)
    elif mutation == "drop_n5_fence":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "n5_verbatim"
        )
    return claims


# ---------------------------------------------------------------------------
# gates: pure functions of the measured facts and the claims
# ---------------------------------------------------------------------------
def evaluate_gates(
    facts: Facts, claims: dict[str, object], elapsed_ns: int
) -> dict[str, bool]:
    authority = facts.authority
    parent_blobs_ok = (
        authority.parent_artifact_blobs
        if claims["parent_pin"] == "resolved"
        else authority.stale_parent_artifact_blobs
    )
    gate_a = bool(
        AUDIT_INPUT_PATHS
        == (
            "docs/ADMISSIBILITY_DIRAC_KAHLER_SEAM_DICHOTOMY_BOUNDED_THEOREM_NOTE_2026-08-19.md",
            "docs/MINIMAL_AXIOMS_2026-06-29.md",
            "docs/audit/data/axiom_premise_nodes.json",
            "docs/ADMISSIBILITY_DIRAC_KAHLER_MASSLESS_SEAM_VERDICT_BOUNDED_THEOREM_NOTE_2026-08-19.md",
            "scripts/admissibility_dirac_kahler_massless_seam_verdict_2026_08_19.py",
            "docs/ADMISSIBILITY_DIRAC_KAHLER_STAGGERED_HERMITIAN_PAIRING_BOUNDED_THEOREM_NOTE_2026-08-19.md",
            "scripts/admissibility_dirac_kahler_staggered_hermitian_pairing_2026_08_19.py",
        )
        and PARENT_ARTIFACTS
        == (BLOCK144_NOTE, BLOCK144_RUNNER, BLOCK143_NOTE, BLOCK143_RUNNER)
        and facts.main_head == claims["main_head"]
        and authority.fixed_authority
        and authority.parent_ref_and_ancestry
        and parent_blobs_ok
    )

    gate_b = bool(
        facts.inertia_calibration
        and facts.hodge_linear_in_moduli
        and facts.quotient_linear_in_moduli
        and facts.builder_matches_symbolic_subfamily
        and facts.builder_matches_committed_fixtures
        and facts.quotient_matches_b134
        and facts.carrier_matches_b144
        and facts.action_matches_b137
        and facts.pairing_matches_b142
        and facts.seam_table == tuple(claims["seam_table"])
        and facts.seam_support_is_odd_shear
        and facts.seam_injective_rank == claims["seam_injective_rank"]
        and facts.seam_zero_when_odd_shear_free
        and facts.moment_vanishes_iff_shear_vanishes
        and facts.shear_free_quotient_diagonal
        and facts.diagonal_law_x_dependent
        and facts.diagonal_law_reduces_to_block144
        and facts.block144_slice_values == b144.HODGE_SLICE_VALUES
        and facts.exact_no_float
    )

    weight_uniform = bool(
        facts.alt_certificate == (facts.system_rank, facts.kernel_dim, True)
        and facts.undressed_certificate
        == (facts.system_rank, facts.kernel_dim, True)
    )
    gate_c = bool(
        facts.system_rank == claims["system_rank"]
        and facts.kernel_dim == MODULUS_DIM - int(claims["system_rank"])
        and facts.kernel_forces_shear_free
        and weight_uniform == bool(claims["necessity_is_weight_uniform"])
        and facts.symbolic_kernel_annihilates
        and facts.symbolic_rows > 0
        and facts.calibration_staircase == CALIBRATION_STAIRCASE
        and facts.calibration_constant == CALIBRATION_CONSTANT
        and facts.calibration_shear_free == CALIBRATION_SHEAR_FREE
        and facts.exact_no_float
    )

    gate_d = bool(
        facts.residual_rank == claims["residual_rank"]
        and facts.residual_forms_span_row_space
        and facts.counterexample_hermitian_edges
        == tuple(claims["counterexample_hermitian_edges"])
        and facts.counterexample_survivors_are_null
        and facts.counterexample_violates_first_form
        and facts.restoration_hermitian_edges == RESTORED_HERMITIAN_EDGES
        and facts.restoration_hodge_inertia == HODGE_INERTIA
        and facts.restoration_seam_zero
        and facts.exact_no_float
    )

    gate_e = bool(
        facts.live_triples == ()
        and facts.live_pairs == LIVE_PAIRS
        and len(facts.live_singletons) == LIVE_SINGLETON_COUNT
        and facts.maximal_live_sets == tuple(claims["maximal_live_sets"])
        and len(facts.maximal_live_sets) == claims["maximal_live_count"]
        and max(len(subset) for subset in facts.maximal_live_sets) == LIVE_BOUND
        and facts.witness_in_cone
        and facts.witness_hermitian_edges
        == tuple(claims["witness_hermitian_edges"])
        and facts.witness_seam_rank == WITNESS_SEAM_RANK
        and facts.witness_hodge_inertia == HODGE_INERTIA
        and facts.witness_mass_present
        and facts.witness_inertias == WITNESS_INERTIAS
        and facts.even_left_in_cone
        and facts.even_left_hermitian_edges == (EVEN_LEFT_EDGE,)
        and facts.even_left_seam_rank == EVEN_LEFT_SEAM_RANK
        and facts.even_left_hodge_inertia == HODGE_INERTIA
        and facts.exact_no_float
    )

    gate_f = bool(
        facts.mass_gram_zero_diagonal
        and facts.mass_gram_locus_is_claimed
        and facts.mass_gram_locus_zero_diagonal
        and facts.mass_gram_block_support == MASS_GRAM_BLOCKS
        and facts.mass_gram_charpoly_splits
        and facts.mass_gram_psd_on_live_sublocus
        == bool(claims["mass_gram_psd_on_live_sublocus"])
        and facts.mass_gram_vanishes_at_dead_point
        and facts.exact_no_float
    )

    gate_g = bool(
        facts.x0_commutes_with_quotient == bool(claims["x0_commutes"])
        and facts.x0_anticommutes_with_currents == len(EDGE_KEYS)
        and facts.x0_hermitian_healed == X0_HERMITIAN_EDGES
        and facts.x0_hermitian_alt == X0_HERMITIAN_EDGES
        and facts.x0_hermitian_undressed == X0_HERMITIAN_EDGES
        and facts.theta_hermitian_on_family == THETA_HERMITIAN_EDGES_ON_FAMILY
        and facts.x0_gram_inertias == (X0_GRAM_INERTIA,) * 3
        and sp.simplify(facts.det_beta - claims["det_beta"]) == 0
        and facts.eps_nilpotent_edges == EPS_NILPOTENT_EDGES
        and facts.eps_jordan_types == frozenset({EPS_JORDAN_TYPE})
        and facts.eps_jordan_indices == frozenset({EPS_JORDAN_INDEX})
        and facts.staircase_jordan_type == STAIRCASE_JORDAN_TYPE
        and facts.staircase_jordan_index == STAIRCASE_JORDAN_INDEX
        and facts.eps_jordan_types != frozenset({facts.staircase_jordan_type})
        and facts.eps_jordan_indices
        != frozenset({facts.staircase_jordan_index})
        and facts.exact_no_float
    )

    required = tuple(claims["required_scope_keys"])
    gate_h = bool(
        set(facts.scope) == set(required)
        and all(facts.scope.values())
        and len(MUTATIONS) == 15
        and len(set(MUTATIONS)) == 15
        and set(MUTATION_GATE) == set(MUTATIONS)
        and set(MUTATION_GATE.values()) == set("ABCDEFGH")
        and N5_FENCE.count("\n") == 7
        and elapsed_ns <= 900 * 1_000_000_000
    )

    return {
        "A": gate_a,
        "B": gate_b,
        "C": gate_c,
        "D": gate_d,
        "E": gate_e,
        "F": gate_f,
        "G": gate_g,
        "H": gate_h,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--mutation", choices=MUTATIONS, default="")
    mutation = parser.parse_args().mutation
    started_ns = time.monotonic_ns()

    # Every measurement happens once, before any mutation flag is consulted,
    # so a mutation can only rewrite a CLAIM.  No gate can cascade into
    # another because no gate feeds a measurement.
    facts = measure()
    elapsed_ns = time.monotonic_ns() - started_ns

    raw_gates = evaluate_gates(facts, build_claims(""), elapsed_ns)
    gate_values = dict(raw_gates)
    if mutation:
        target = MUTATION_GATE[mutation]
        gate_values = evaluate_gates(
            facts, build_claims(mutation), elapsed_ns
        )
        changed = {
            key for key in raw_gates if raw_gates[key] != gate_values[key]
        }
        if changed - {target} or gate_values[target]:
            raise AssertionError(
                "mutation did not fail exactly its own gate"
            )

    checks = Checks()
    checks.check(
        "A-authority",
        "main plus the committed Block 144 note/runner and Block 143 note/runner artifacts are content-bound",
        gate_values["A"],
    )
    checks.check(
        "B-seam-law",
        "the cover Hodge and H_q are exactly linear in the 64 per-cell moduli (nu,a,b,1/nu) with a=nu/(1-sg^2), b=-nu*sg/(1-sg^2), the substitution reproducing b142's builder on a symbolic sub-family and on the committed fixtures; the seam Gram H_q[-,+] has exactly the eight entries {(0,5):b_10/4,(1,6):b_11/4,(2,7):b_12/4,(3,4):b_13/4,(4,3):-b_33/4,(5,0):-b_30/4,(6,1):-b_31/4,(7,2):-b_32/4}, injective of rank 8 in the odd-time-slice shear moments, zero iff the odd-slice shears vanish; and the zero-shear stratum is diagonal with h(p,y)=(nu(p,y)+nu(p,y-1)+nu(p-1,y)+1/nu(p-1,y-1))/4 reducing to Block 144's law and its four fixture values",
        gate_values["B"],
    )
    checks.check(
        "C-necessity-theorem",
        "Hermiticity of all sixteen healed pairings identically in m is a linear system of rank 18 on the 64-dimensional modulus space whose 46-dimensional kernel lies inside {b=0}, so atlas-global Hermiticity forces the shear off; the certificate holds symbolically in (s_x,s_t), at both weight vectors and for the undressed atlas, and the model reproduces the committed calibration triple (staircase 0/16, constant 1/16 at edge (1,2), shear-free 16/16)",
        gate_values["C"],
    )
    checks.check(
        "D-converse-refinement",
        "shear-free is necessary but NOT sufficient: the residual system on the shear-free stratum has rank exactly 2, spanned by the two x-alternating volume forms, and nu=1 with nu(0,1)=2 violates the first and leaves only the four trivial edges whose pairing is identically zero, while adding nu(0,3)=2 restores 16/16 with H_q inertia (16,0,0) and a dead seam",
        gate_values["D"],
    )
    checks.check(
        "E-live-seam-residue",
        "no three edges can be Hermitian with a live seam, and the maximal live sets are exactly eight: the four cover-time-odd-left pairs {(2,0),(2,1)},{(3,0),(3,1)},{(2,3),(3,2)},{(2,2),(3,3)} and the four cover-time-even-left singletons {(0,2)},{(0,3)},{(1,2)},{(1,3)}; the self-edge witness (sigma=3/5 on (1,1),(1,3),(3,1),(3,3) and sigma=15/32, nu=799/512 on (1,0),(1,2),(3,0),(3,2)) makes (2,2),(3,3) Hermitian with the mass present, seam rank 8, H_q (16,0,0) and inertias {(6,0,2),(2,0,6)}, while the even-left carrier (sigma=-3/5,nu=3 on the even slices, sigma=3/5,nu=1 on the odd) makes edge (0,2) Hermitian with a rank-8 seam",
        gate_values["E"],
    )
    checks.check(
        "F-split-mass-gram",
        "on the mass-block Hermiticity locus b_10=b_13, b_11=b_12, b_30=b_33, b_31=b_32 the Gram [theta*H_q]_{++} has structurally zero diagonal and exactly four hyperbolic 2x2 blocks at (0,3),(1,2),(4,5),(6,7) with spectrum +-b_33/4, +-b_32/4, +-b_13/4, +-b_12/4, so it is never positive semidefinite anywhere on the live sublocus and holds only vacuously at the all-zero point where the Gram itself vanishes",
        gate_values["F"],
    )
    checks.check(
        "G-x0-complement",
        "[X_0,H_q]=0 on the whole symbolic family and {X_0,K_ij}=0 on 16/16 edges, so the X_0 pairing is Hermitian 16/16 at the healed, control and undressed weights against 0/16 for the canonical lattice theta on the same family, yet [X_0*H_q]_{++} has inertia exactly (4,0,4) on the staircase, the witness and the flat carrier; and the Block 143 skew census does not deform continuously, det beta = eps^8/(65536(1-eps^2)^8) with nilpotent type (2,2,1,1,1,1) of index 2 on four edges at eps=3/5 against the staircase's (3,3,1,1) of index 3",
        gate_values["G"],
    )
    checks.check(
        "H-note-scope",
        "the seam law and its injectivity, the rank-18 necessity theorem, the two residual volume conditions and the not-sufficient reading, the dichotomy statement, the corrected live sets with their even-left singletons and odd-left pairs, the witness, the split mass Gram with its vacuous caveat, the carrier-uniform X_0 complement with its (4,0,4) Gram and its discontinuity, the tooling and independence disclosures, the firewalls, and the exact N5 fence are present",
        gate_values["H"],
    )
    checks.report()
    print(N5_FENCE)
    return checks.finish()


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except SystemExit:
        raise
    except Exception as error:
        print(f"[FAIL] INTERNAL-EXCEPTION: {type(error).__name__}: {error}")
        print("TOTAL: PASS=0 FAIL=1")
        raise
